`timescale 1ns/1ps

// File-driven bit-exact test for emg_bandpass. Reads bandpass_stim.txt
// (one signed decimal per line, generated by tools/emg_reference.py),
// writes bandpass_out.csv and lets the Python model compare.
module emg_bandpass_tb;
    reg clk = 1'b0;
    reg rst_n = 1'b0;
    reg sample_valid = 1'b0;
    reg signed [23:0] sample_in = 24'sd0;
    wire filtered_valid;
    wire signed [23:0] filtered_out;
    reg signed [23:0] prev_in = 24'sd0;
    integer stim_fd, out_fd, code, value, count;

    always #5 clk = ~clk;

    emg_bandpass dut (
        .clk(clk), .rst_n(rst_n), .sample_valid(sample_valid),
        .sample_in(sample_in), .filtered_valid(filtered_valid),
        .filtered_out(filtered_out)
    );

    always @(posedge clk) begin
        if (filtered_valid)
            $fdisplay(out_fd, "%0d,%0d", prev_in, filtered_out);
    end

    initial begin
        stim_fd = $fopen("bandpass_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("EMG bandpass TB FAILED: cannot open bandpass_stim.txt");
            $finish;
        end
        out_fd = $fopen("bandpass_out.csv", "w");
        $fdisplay(out_fd, "in,out");
        repeat (4) @(posedge clk);
        rst_n = 1'b1;
        repeat (2) @(posedge clk);
        count = 0;
        forever begin
            code = $fscanf(stim_fd, "%d", value);
            if (code != 1) begin
                repeat (4) @(posedge clk);
                $fclose(stim_fd);
                $fclose(out_fd);
                $display("EMG bandpass TB completed: samples=%0d", count);
                $finish;
            end
            @(negedge clk);
            prev_in = value[23:0];
            sample_in = value[23:0];
            sample_valid = 1'b1;
            @(negedge clk);
            sample_valid = 1'b0;
            count = count + 1;
        end
    end
endmodule

